/* From Uiverse.io by vinodjangid07 - Tags: checkbox, save, click effect, bookmark */
.__UIV_SCOPE__ .bookmark {
  position: relative;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ #checkboxInput {
  display: none;
}

.__UIV_SCOPE__ .svgIcon {
  height: 30px;
}

.__UIV_SCOPE__ .svgIcon path {
  fill: rgb(153, 153, 153);
}

.__UIV_SCOPE__ .bookmark::before {
  content: "\002B";
  position: absolute;
  color: rgb(255, 255, 255);
  font-size: 1.2em;
  top: 1px;
}

.__UIV_SCOPE__ #checkboxInput:checked + .bookmark::before {
  content: "\2713";
  font-size: 0.70em;
  top: 5px;
}

.__UIV_SCOPE__ #checkboxInput:checked + .bookmark .svgIcon path {
  fill: rgb(121, 199, 3);
}

.__UIV_SCOPE__ #checkboxInput:active + .bookmark .svgIcon path {
  fill: rgb(204, 204, 204);
}

.__UIV_SCOPE__ .bookmark::after {
  content: "";
  background-color: rgba(56, 105, 0, 0.342);
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  z-index: -1;
}

.__UIV_SCOPE__ #checkboxInput:checked + .bookmark::after {
  animation: puff-out-center .5s cubic-bezier(0.165, 0.840, 0.440, 1.000) both;
}

@keyframes puff-out-center {
  0% {
    transform: scale(1);
    filter: blur(0px);
    opacity: 1;
  }

  100% {
    transform: scale(9);
    filter: blur(1px);
    opacity: 0;
  }
}
